{
  "name": "send_email",
  "description": "Send an email to a given address with a subject and body",
  "inputSchema": {
    "type": "object",
    "properties": {
      "to": { "type": "string", "description": "Recipient email address" },
      "subject": { "type": "string" },
      "body": { "type": "string" }
    },
    "required": ["to", "subject", "body"]
  }
}

{
  "name": "create_task",
  "description": "Creates a new task in the user's task list. Use this when the user asks to add, remember, or track something as a to-do item.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "title": { "type": "string", "description": "Short task title" },
      "due_date": { "type": "string", "description": "Optional ISO 8601 date" }
    },
    "required": ["title"]
  }
}
